head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > drawType]<br/>GridView 컴포넌트가 렌더링 되는 방식을 설정합니다.",
    "validation" : [
        "GridView 의 세로(Y 축) 스크롤과 데이터 렌더링 방식을 결정합니다.",
        "virtual 설정 시, 가상 스크롤 방식으로 렌더링합니다.",
        "미설정 시, 가상 스크롤 방식으로 렌더링합니다.",
        "virtual 설정 시, GridView 의 뷰포트에 보이는 데이터만 렌더링하므로 대용량 데이터 처리에 적합합니다.",
        "virtual 설정 시, 모든 스크롤 동작이 WebSquare 엔진에 의해 관리됩니다.",
        "virtual 설정 시, onscrollstart, onscrollend, onscrolly 이벤트가 발생합니다.",
        "native 설정 시, 웹브라우저 스크롤 방식으로 렌더링합니다.",
        "native 설정 시, 모든 데이터를 사전에 렌더링하므로 visibleRowNum 속성이 'all' 로 강제 설정됩니다. 따라서 GridView 의 높이(Height)는 반드시 설정해야 합니다.",
        "native 설정 시, 세로 스크롤이 웹브라우저에 의해 관리되므로 움직임이 자연스럽고 적은 데이터에 적합합니다.",
        "native 설정 시, onscrollstart 는 발생하지 않고, onscrollend 는 최하단 도달 시 발생하며 onscrolly 는 발생합니다.",
        "native 설정 시, overflowY, fixedRow, wheelRows, wheelStop 등의 속성이 무시됩니다.",
        "accessibility=true 이면 'native' 로 강제 적용되며 visibleRowNum, senseReader, focusMove, keyMoveEditMode, scrollFocus, titleAuto, sortHeaderDiv 등의 접근성 관련 속성이 연쇄적으로 변경됩니다.",
        "adaptive 속성에 의해 행-열 전환(crosstab) 구조로 변환 시 'virtual' 로 임시 적용되며, Adaptive 모드가 해제되면 원래 값으로 복원됩니다.",
        "GridView 의 각 Row 높이가 다른 경우 drawType 속성을 'native'로 설정하는 것을 권장합니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출 (gdl_boolean 등)
    $c.gcm.createCommonDatalist();

    // 정적/itemset select1 은 초기 selectedIndex 미적용 -> 기본값 명시 설정
    //  - gdl_boolean 코드값 : 미설정="1" / true="2" / false="3"
    con_drawType.setValue("native");        // 기본 시나리오 : drawType=native
    con_accessibility.setValue("1");        // 미설정
    con_adaptive.setSelectedIndex(0);       // 미설정

    // comp 초기 생성 (비동기 dynamicCreate 완료까지 대기)
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  - drawType 은 @dynamic N 이므로 con 변경은 Target 재생성으로만 반영된다.
//  - 전제 : 데이터 30행 / 그리드 700x200px(높이 고정) / visibleRowNum=5
//           overflowY=scroll, fixedRow=2, wheelRows=5, wheelStop=true 를 고정 부여하여
//           native 에서 해당 속성이 무시되는지 대조할 수 있게 한다.
//           adaptiveThreshold=1000 을 고정 부여하여 브라우저 창 너비 조절로 적응형 적용/해제를 확인한다.
scwin.comp_init = async function () {
    // 기존 target / dataList 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let vDrawType = con_drawType.getValue();        // '' / 'virtual' / 'native'
    let vAcc = con_accessibility.getText();         // '' / 'true' / 'false'
    let vAdaptive = con_adaptive.getValue();        // '' / 'crosstab'

    // 측정값 초기화 (스크롤 이벤트 카운트 / 세로 스크롤 1회 이동 Row 수)
    scwin.gVar = {
        "cntScrollStart" : 0,
        "cntScrollEnd" : 0,
        "cntScrollY" : 0,
        "prevTopRow" : 0,
        "lastMoveRows" : -1
    };

    // 테스트 참고 라벨 (target 생성 전, 가장 먼저 생성)
    let lbl = '';
    lbl += '[전제] 데이터 30행, 그리드 700x200px(높이 고정), visibleRowNum=5, overflowY=scroll, fixedRow=2, wheelRows=5, wheelStop=true, adaptiveThreshold=1000';
    lbl += '\n[현재] drawType=' + (vDrawType === '' ? '(미설정)' : vDrawType) + ', accessibility=' + (vAcc === '' ? '(미설정)' : vAcc) + ', adaptive=' + (vAdaptive === '' ? '(미설정)' : vAdaptive);
    lbl += '\n[절차] con 선택 -> Target 재생성 -> 그리드 위에서 마우스 휠 1회 -> 최하단까지 스크롤 -> [렌더링 방식 확인] 과 [무시되는 속성 확인] 클릭 -> 다시 최상단까지 스크롤 -> [스크롤 이벤트 발생 확인] 클릭';
    lbl += '\n[확인] fixedRow 가 동작하면 스크롤 후에도 화면 최상단 Row 의 첫 Cell 값이 col1_1 로 유지된다. wheelRows 가 동작하면 휠 1회 이동 Row 수가 5 로 일정하고, wheelStop 이 동작하면 그리드 최하단에서 휠을 더 굴려도 그리드 바깥 영역 스크롤 위치가 0px 로 유지된다';
    lbl += '\n[확인] adaptive=crosstab 은 브라우저 창 너비를 1000px 이하로 줄이면 적용, 다시 넓히면 해제되므로 각 상태에서 [렌더링 방식 확인] 을 클릭해 drawType 반영값을 대조';
    lbl += '\n[확인] [Row 높이 상이 시 렌더 확인] 은 홀수 Row 를 60px 로 높여 Row 높이를 서로 다르게 만든다. 클릭 후 최하단까지 스크롤해 마지막 Row(col1_30) 까지 정상적으로 표시되는지 virtual / native 를 대조';
    $c.gcm.createLabel('label="' + lbl + '"', '', 'label1');

    // dataList 생성 (30행)
    await $c.gcm.createDynamicDataList('', '', 'dlt_bind', '', 30);

    // 조건 설정 (빈값은 createCList 에서 자동 제외)
    let properties = {
        drawType          : vDrawType,
        accessibility     : vAcc,
        adaptive          : vAdaptive,
        adaptiveThreshold : "1000",
        dataList          : "data:dlt_bind",
        visibleRowNum     : "5",
        overflowY         : "scroll",
        fixedRow          : "2",
        wheelRows         : "5",
        wheelStop         : "true"
    };
    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onscrollstart", "onscrollend", "onscrolly"]);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' ' + eList + ' checkAllType="false" id="" style="width:700px;height:200px;">';
    strTarget += '<w2:caption style="" id="caption1" value="drawType 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="160" style="" inputType="text" id="column1" value="name1"></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="text" id="column2" value="name2"></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="text" id="column3" value="name3"></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="text" id="column4" value="name4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="160" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// 현재 화면 최상단에 보이는 Row 인덱스
//  - 엔진 가상 스크롤(virtual) : 엔진이 관리하는 rowIndex
//  - 웹브라우저 스크롤(native) : dataLayer 의 픽셀 스크롤 위치를 Row 높이로 환산
scwin.getTopRowIndex = function () {
    let dataLayer = target1.render.querySelector("div[id$='_dataLayer']");
    let bodyRow = target1.render.querySelector("tr.grid_body_row");
    let rowHeight = (bodyRow && bodyRow.offsetHeight > 0) ? bodyRow.offsetHeight : 1;

    if (dataLayer && dataLayer.scrollHeight > dataLayer.clientHeight) {
        return Math.round(dataLayer.scrollTop / rowHeight);
    }

    return target1.getTopRowIndex();
}



// 세로 스크롤을 웹브라우저가 관리하는지 여부
scwin.isBrowserScroll = function () {
    let dataLayer = target1.render.querySelector("div[id$='_dataLayer']");
    return dataLayer !== null && dataLayer.scrollHeight > dataLayer.clientHeight;
}



// WebSquare 엔진이 관리하는 세로 스크롤 영역의 사용 여부
scwin.isEngineScroll = function () {
    let scrollYDiv = target1.render.querySelector("div[id$='_scrollY_div']");
    if (scrollYDiv === null) {
        return false;
    }
    return window.getComputedStyle(scrollYDiv).visibility === "visible" && scrollYDiv.scrollHeight > scrollYDiv.clientHeight;
}



// 그리드를 감싸는 바깥 스크롤 영역의 스크롤 위치
//  - 휠이 그리드 밖으로 전파되었는지 확인용 (wheelStop 반영 여부)
scwin.getOuterScrollTop = function () {
    let el = target1.render.parentElement;

    while (el) {
        if (el.scrollHeight > el.clientHeight + 1) {
            return Math.round(el.scrollTop);
        }
        el = el.parentElement;
    }

    return 0;
}



// 화면 최상단에 보이는 Body Row 의 첫 Cell 값
scwin.getTopVisibleCellText = function () {
    let dataLayer = target1.render.querySelector("div[id$='_dataLayer']");
    let arrRow = target1.render.querySelectorAll("tr.grid_body_row");
    let topLine = dataLayer.getBoundingClientRect().top;

    for (let i = 0; i < arrRow.length; i++) {
        let rect = arrRow[i].getBoundingClientRect();
        if (rect.height > 0 && rect.bottom > topLine + 1) {
            let td = arrRow[i].querySelector("td[id*='_cell_']");
            return (td === null) ? "" : td.textContent;
        }
    }

    return "";
}



// 스크롤 이벤트 핸들러 (발생 횟수 누적)
scwin.target1_onscrollstart = function () {
    scwin.gVar.cntScrollStart++;
}

scwin.target1_onscrollend = function () {
    scwin.gVar.cntScrollEnd++;
}

scwin.target1_onscrolly = function (e) {
    scwin.gVar.cntScrollY++;

    // 세로 스크롤 1회당 이동한 Row 수 측정 (wheelRows 반영 여부 확인용)
    let curTopRow = scwin.getTopRowIndex();
    scwin.gVar.lastMoveRows = Math.abs(curTopRow - scwin.gVar.prevTopRow);
    scwin.gVar.prevTopRow = curTopRow;
}



// 렌더링 방식 확인
//  - drawType 반영값(accessibility 강제 / adaptive 임시 적용 포함)
//  - visibleRowNum 강제값, 실제 렌더된 Body Row 수, 세로 스크롤 관리 주체
scwin.btn_drawTypeCheck_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    let bAdaptive = target1.render.className.indexOf("w2grid_adaptive_crosstab") > -1;
    let arrBodyRow = target1.render.querySelectorAll("tr.grid_body_row");

    bottom.setReturnValue("[설정] drawType : " + (con_drawType.getValue() === "" ? "미설정" : con_drawType.getValue())
        + ", accessibility : " + (con_accessibility.getText() === "" ? "미설정" : con_accessibility.getText())
        + ", adaptive : " + (con_adaptive.getValue() === "" ? "미설정" : con_adaptive.getValue())
        + " (적응형 적용 : " + bAdaptive + ", 브라우저 너비 : " + window.innerWidth + "px / adaptiveThreshold : 1000)");
    bottom.setReturnValue("drawType 옵션 반영값 : " + target1.options.drawType);
    bottom.setReturnValue("visibleRowNum 옵션 반영값 : " + target1.options.visibleRowNum + " (설정값 : 5)");
    bottom.setReturnValue("전체 데이터 : " + dlt_bind.getRowCount() + " 행, 실제 렌더된 Body Row 수 : " + arrBodyRow.length);
    bottom.setReturnValue("세로 스크롤 관리 주체 : " + (scwin.isBrowserScroll() ? "웹브라우저" : "WebSquare 엔진"));
}



// 무시되는 속성 확인 (overflowY / fixedRow / wheelRows / wheelStop)
scwin.btn_ignoredOptionCheck_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.setReturnValue("overflowY=scroll -> WebSquare 엔진 세로 스크롤 영역 사용 여부 : " + scwin.isEngineScroll());
    bottom.setReturnValue("fixedRow=2 -> 화면 최상단 Row 의 첫 Cell 값 : " + scwin.getTopVisibleCellText());
    bottom.setReturnValue("wheelRows=5 / wheelStop=true -> 휠 1회당 이동 Row 수 : " + scwin.gVar.lastMoveRows + ", 그리드 바깥 영역 스크롤 위치 : " + scwin.getOuterScrollTop() + "px");
}



// 스크롤 이벤트 발생 확인 (출력 후 카운트 초기화)
scwin.btn_scrollEventCheck_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");

    bottom.setReturnValue("onscrollstart : " + scwin.gVar.cntScrollStart + " 회, onscrollend : " + scwin.gVar.cntScrollEnd + " 회, onscrolly : " + scwin.gVar.cntScrollY + " 회");

    scwin.gVar.cntScrollStart = 0;
    scwin.gVar.cntScrollEnd = 0;
    scwin.gVar.cntScrollY = 0;
}



// Row 높이 변경 (각 Row 높이가 다른 경우 권장 방식 확인)
//  - 짝수 Row 의 Cell 에 높은 style 을 적용해 Row 높이를 서로 다르게 만든 뒤
//    렌더 결과(Row 별 실제 높이 / 마지막 Row 전체 표시 여부)를 확인한다.
scwin.btn_rowHeightCheck_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    let dataLen = dlt_bind.getRowCount();

    for (let i = 0; i < dataLen; i++) {
        if (i % 2 === 1) {
            target1.setCellStyle(i, 0, "height", "60px");
        }
    }

    let arrBodyRow = target1.render.querySelectorAll("tr.grid_body_row");
    let arrHeight = [];
    for (let i = 0; i < Math.min(arrBodyRow.length, 4); i++) {
        arrHeight.push(arrBodyRow[i].offsetHeight);
    }

    bottom.setReturnValue("Row 높이를 서로 다르게 적용한 후 상위 4개 Row 의 실제 높이(px) : " + arrHeight.join(", "));
}
